-- development agents, meeting intelligence, and enterprise knowledge.

insert into public.tools (
  name, description, full_description, url, logo_url,
  pricing_type, pricing_start_at, pricing_summary, pricing_details,
  pricing_currency, pricing_url, pricing_verified_at,
  korean_support_level, is_verified, source_verified, hands_on_verified,
  api_tested, korean_tested, verification_level, verification_notes,
  is_domestic, has_api, api_url, ai_type, tool_scope,
  primary_features, secondary_features, key_benefits, best_for, limitations,
  verification_sources, verified_at, updated_at
)
select * from (values
('Microsoft Copilot','웹 검색·문서·이미지 작업을 지원하고 Microsoft 서비스와 연결되는 범용 AI #AI챗봇 #웹검색 #이미지생성 #생산성','Microsoft Copilot은 질문 응답, 웹 기반 조사, 문서 작성과 이미지 생성을 제공하며 Microsoft 계정과 Microsoft 365 앱 생태계에 연결되는 범용 AI 도우미입니다.','https://copilot.microsoft.com/','https://www.microsoft.com/favicon.ico','Freemium','$0','무료 기본 사용 · Copilot Pro 월 $20',array['무료 버전은 제한된 AI 사용과 이미지 생성 기능을 제공합니다.','Copilot Pro는 사용자당 월 $20이며 최신 모델 우선 접근과 더 많은 사용량을 제공합니다.','Microsoft 365 앱 내 기능은 지역·구독·계정 유형에 따라 달라질 수 있습니다.'],'USD','https://www.microsoft.com/en-us/store/b/copilotpro',now(),'Full Support',true,true,false,false,false,'official_sources','공식 제품·가격 자료를 확인했습니다. 로그인 후 기능, 한국어 품질, 결제는 직접 테스트하지 않았습니다.',false,false,null,'Native','general',array['대화형 AI','웹 기반 검색·조사','문서·이미지 생성'],array['Microsoft 365 연동','음성 대화','개인화'],array['무료 범용 AI 진입점','Microsoft 생태계 연동','웹 정보와 생성 기능 결합'],array['일상 검색과 문서 작성을 함께 하는 사용자','Microsoft 서비스를 사용하는 개인'],array['Microsoft 365 Copilot과 개인용 Copilot Pro는 별도 상품입니다.','기능과 사용량은 지역·계정·플랜에 따라 달라집니다.','중요한 답변은 원문 출처를 확인해야 합니다.'],array['https://copilot.microsoft.com/','https://www.microsoft.com/en-us/store/b/copilotpro'],now(),now()),
('Manus','조사·자료 제작·웹사이트 구축을 비동기 작업으로 수행하는 범용 AI 에이전트 #AI에이전트 #리서치 #웹사이트제작 #자동화','Manus는 복잡한 요청을 계획하고 웹 조사, 보고서·슬라이드 제작, 데이터 처리와 웹사이트 구축을 클라우드 환경에서 실행하는 범용 AI 에이전트입니다.','https://manus.im/','https://manus.im/favicon.ico','Freemium','$0','Free 일 300크레딧 · Pro 월 $20부터',array['Free는 일 300크레딧과 제한된 Agent Mode, 1개 동시 작업을 제공합니다.','Pro는 월 $20부터 4,000크레딧과 고급 조사·웹사이트 배포·슬라이드 생성을 제공합니다.','작업 복잡도와 사용 자원에 따라 실제 크레딧 소모가 달라집니다.'],'USD','https://manus.im/pricing',now(),'Full Support',true,true,false,false,false,'official_sources','공식 제품·요금·도움말을 확인했습니다. 에이전트 실행 결과와 한국어 품질은 직접 테스트하지 않았습니다.',false,false,null,'Native','general',array['자율 작업 수행','심층·광범위 조사','웹사이트·슬라이드 제작'],array['예약 작업','클라우드 브라우저','데이터 분석'],array['여러 단계를 한 작업으로 위임','결과물 제작과 배포 연결','무료 일일 크레딧'],array['조사와 결과물 제작을 함께 맡기려는 사용자','반복 작업을 비동기로 처리하는 팀'],array['복잡한 작업은 크레딧을 빠르게 소비할 수 있습니다.','외부 서비스 조작 전 권한과 결과를 검토해야 합니다.','자동 생성 웹사이트는 별도 호스팅 사용료가 발생할 수 있습니다.'],array['https://manus.im/docs/introduction/plans','https://help.manus.im/en/articles/11711111-what-is-the-current-membership-pricing-for-manus'],now(),now()),
('CodeRabbit','Pull Request와 IDE에서 코드 문맥을 분석해 리뷰·수정안을 제시하는 AI #코드리뷰 #Git #코딩 #AI에이전트','CodeRabbit은 GitHub·GitLab Pull Request와 IDE·CLI에서 변경 코드를 분석하고 요약, 문제 탐지, 자동 수정과 조직별 리뷰 규칙을 적용하는 AI 코드 리뷰 플랫폼입니다.','https://www.coderabbit.ai/','https://www.coderabbit.ai/favicon.ico','Freemium','$0','Free PR 요약·IDE 리뷰 · Pro 연간 월 $24/사용자',array['Free는 공개·비공개 저장소의 PR 요약과 IDE·CLI 리뷰를 제공합니다.','Pro는 연간 결제 사용자당 월 $24이며 전체 PR 리뷰, 분석과 통합 기능을 제공합니다.','Pro Plus는 연간 결제 사용자당 월 $48이며 고급 검사와 더 높은 한도를 제공합니다.'],'USD','https://www.coderabbit.ai/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품·가격·지식문서를 확인했습니다. 실제 저장소 연결과 리뷰 정확도는 직접 테스트하지 않았습니다.',false,true,'https://docs.coderabbit.ai/','Native','specialized',array['AI Pull Request 리뷰','코드 문맥 분석','자동 수정 제안'],array['IDE·CLI 리뷰','린터·SAST 연동','Enterprise API'],array['PR 단계에서 품질 문제 발견','조직 리뷰 규칙 자동 적용','무료 코드 리뷰 진입점'],array['Pull Request 검토를 자동화하는 개발팀','일관된 코드 리뷰 기준이 필요한 조직'],array['고급 API 접근은 Enterprise 범위입니다.','AI 제안은 보안·설계 검토와 테스트를 대체하지 않습니다.','비공개 저장소 연결 전 데이터 처리 정책을 확인해야 합니다.'],array['https://www.coderabbit.ai/pricing','https://kb.coderabbit.ai/articles/2544860735-how-do-I-learn-more-about-coderabbit-subscription-plans'],now(),now()),
('Devin','개발 작업을 계획하고 코드 작성·실행·검증과 Pull Request 생성을 수행하는 AI #코딩 #AI에이전트 #개발자동화 #코드리뷰','Devin은 격리된 개발 환경에서 저장소를 이해하고 작업을 계획해 코드 작성, 명령 실행, 테스트와 Pull Request 생성을 수행하는 소프트웨어 개발 AI 에이전트입니다.','https://devin.ai/','https://devin.ai/favicon.ico','Freemium','$0','Free 제한 사용 · Pro 월 $20',array['Free는 제한된 Devin 사용과 Devin Review·DeepWiki 접근을 제공합니다.','Pro는 개인용 월 $20, Max는 월 $200입니다.','Teams는 월 최소 $80이며 Full Seat는 월 $40이고 초과 사용은 온디맨드 크레딧으로 과금됩니다.'],'USD','https://devin.ai/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품·요금·개발자 문서를 확인했습니다. 저장소 작업과 API 호출은 직접 테스트하지 않았습니다.',false,true,'https://docs.devin.ai/api-reference/overview','Native','specialized',array['자율 코딩 작업','코드 실행·테스트','Pull Request 생성'],array['Devin Review','DeepWiki','Enterprise API'],array['계획부터 검증까지 개발 작업 위임','클라우드 개발 환경 제공','이슈·협업 도구 연동'],array['명확한 개발 작업을 위임하는 팀','반복적인 수정과 검증을 자동화하는 개발자'],array['작업 시간과 복잡도에 따라 온디맨드 비용이 발생합니다.','생성 코드와 명령은 사람이 검토해야 합니다.','일반 API 접근 범위는 플랜과 조직 권한에 따라 제한될 수 있습니다.'],array['https://docs.devin.ai/admin/billing','https://docs.devin.ai/api-reference/v2/consumption/daily-consumption'],now(),now()),
('Dify','LLM 앱·RAG·워크플로·에이전트를 시각적으로 만들고 API로 배포하는 오픈소스 플랫폼 #AI앱개발 #RAG #워크플로 #API','Dify는 여러 언어 모델을 연결해 채팅 앱, 지식검색 RAG, 에이전트와 워크플로를 구성하고 API·웹앱으로 배포할 수 있는 오픈소스 LLM 애플리케이션 플랫폼입니다.','https://dify.ai/','https://dify.ai/favicon.ico','Freemium','$0','Cloud Sandbox 무료 · Professional 연 $590/워크스페이스',array['Cloud Sandbox는 200 메시지크레딧, 5개 앱과 월 5,000 API 호출 한도를 제공합니다.','Professional은 연 $590/워크스페이스에 월 5,000 메시지크레딧을 제공합니다.','오픈소스 Community는 무료 자체 호스팅이 가능하지만 모델·서버 비용은 별도입니다.'],'USD','https://dify.ai/pricing',now(),'Full Support',true,true,false,false,false,'official_sources','공식 제품·가격·문서를 확인했습니다. 앱 배포, 한국어 RAG 품질과 API 호출은 직접 테스트하지 않았습니다.',false,true,'https://docs.dify.ai/api-reference','Augmented','specialized',array['LLM 앱 제작','RAG 지식베이스','에이전트·워크플로'],array['API 배포','플러그인','자체 호스팅'],array['여러 모델과 도구 통합','시각적 AI 앱 제작','오픈소스 자체 배포 선택'],array['AI 서비스를 빠르게 구축하는 개발자·기획자','사내 RAG와 업무 에이전트를 운영하는 조직'],array['클라우드 요금과 LLM 제공자 사용료가 함께 발생할 수 있습니다.','Community 사용은 오픈소스 라이선스 조건을 확인해야 합니다.','프로덕션 운영에는 보안·관찰성·비용 통제가 필요합니다.'],array['https://www.dify.ai/pricing','https://docs.dify.ai/guides/knowledge-base/retrieval'],now(),now()),
('Read AI','회의 전사·요약과 이메일·메시지·회의 지식 검색을 결합한 AI #회의록 #전사 #AI검색 #생산성','Read AI는 Zoom·Teams·Meet 회의를 전사하고 요약·실행 항목·대화 지표를 생성하며 회의, 이메일과 메시지를 연결해 Ask Read 검색을 제공합니다.','https://www.read.ai/','https://www.read.ai/favicon.ico','Freemium','$0','Free 월 5회의 · Pro 연간 월 $15/사용자',array['Free는 월 5개 회의 전사·요약과 기본 통합을 제공합니다.','Pro는 연간 결제 사용자당 월 $15, 월간 결제는 $19.75입니다.','Enterprise는 연간 월 $22.50이며 영상 재생과 더 많은 업로드를 제공합니다.'],'USD','https://www.read.ai/plans-pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품·가격 자료를 확인했습니다. 회의 참가·녹음·전사 정확도는 직접 테스트하지 않았습니다.',false,true,'https://support.read.ai/hc/en-us/categories/25927172788115-API','Native','specialized',array['회의 전사·요약','실행 항목·코칭','업무 지식 검색'],array['이메일·메시지 연결','회의 지표','API·웹훅'],array['회의와 비동기 업무 정보 통합','무료 월 5회의','검색과 회의 코칭 제공'],array['회의 후속 업무를 줄이려는 팀','분산된 업무 대화를 검색하려는 조직'],array['공식 지원 언어 목록에서 한국어는 확인되지 않았습니다.','회의 녹음과 분석 전 참가자 동의가 필요합니다.','무료 플랜은 회의 길이와 월 처리량이 제한됩니다.'],array['https://www.read.ai/plans-pricing'],now(),now()),
('Relevance AI','업무별 AI 에이전트와 도구·다중 에이전트 팀을 만드는 플랫폼 #AI에이전트 #업무자동화 #노코드 #API','Relevance AI는 영업·지원·운영 업무를 위한 에이전트, 도구와 다중 에이전트 워크포스를 구성하고 2,000개 이상 통합 및 API·MCP로 연결하는 기업용 플랫폼입니다.','https://relevanceai.com/','https://relevanceai.com/favicon.ico','Paid',null,'Enterprise 문의',array['현재 공개 가격 페이지는 Enterprise 맞춤 견적 중심입니다.','무제한 에이전트·도구·사용자와 2,000개 이상 통합을 안내합니다.','호출·회의 에이전트와 평가·분석·SSO·감사 로그가 Enterprise 범위에 포함됩니다.'],'USD','https://relevanceai.com/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품·가격·개발자 페이지를 확인했습니다. 에이전트 실행과 API 호출은 직접 테스트하지 않았습니다.',false,true,'https://relevanceai.com/docs','Native','specialized',array['업무 AI 에이전트 제작','다중 에이전트 워크포스','도구·통합 구성'],array['에이전트 평가','API·MCP','권한·감사'],array['업무 역할 단위 에이전트 구성','다양한 업무 앱 연결','기업 관리·평가 기능'],array['AI 업무 인력을 구축하려는 기업','영업·지원·운영 자동화 팀'],array['공개 셀프서비스 가격이 없어 견적 확인이 필요합니다.','외부 시스템 쓰기 권한과 승인 단계를 설계해야 합니다.','에이전트 결과의 정확도와 비용을 업무별로 평가해야 합니다.'],array['https://relevanceai.com/pricing','https://relevanceai.com/docs'],now(),now()),
('Gumloop','AI 에이전트와 시각적 워크플로로 웹·문서·업무 앱 작업을 자동화하는 도구 #AI에이전트 #워크플로 #노코드 #자동화','Gumloop은 AI 모델, 웹 데이터, 문서와 업무 앱을 노드 기반 워크플로 및 대화형 에이전트로 연결해 반복 업무를 자동화하는 노코드 플랫폼입니다.','https://www.gumloop.com/','https://www.gumloop.com/favicon.ico','Freemium','$0','Free 월 5,000크레딧 · Pro 월 $37부터',array['Free는 월 5,000크레딧과 제한된 동시 실행을 제공합니다.','Pro는 월 $37부터 20,000크레딧과 협업·공유 기능을 제공합니다.','워크플로는 기본 실행과 유료 노드, 에이전트는 모델·도구 사용량에 따라 크레딧을 소비합니다.'],'USD','https://www.gumloop.com/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품·가격·크레딧 문서를 확인했습니다. 워크플로 실행과 결과 품질은 직접 테스트하지 않았습니다.',false,true,'https://docs.gumloop.com/api-reference/introduction','Native','specialized',array['AI 워크플로 제작','대화형 업무 에이전트','웹·문서 자동화'],array['100개 이상 통합','BYOK','API·MCP'],array['비개발자용 복잡한 AI 자동화','예측 가능한 워크플로 크레딧','팀 공유와 외부 앱 연결'],array['반복 조사·데이터 입력을 자동화하는 팀','노코드 AI 업무 흐름을 만드는 운영자'],array['에이전트 크레딧은 대화·모델·도구에 따라 변동됩니다.','반복문과 데이터 보강 노드는 비용이 커질 수 있습니다.','실패 전 실행된 노드에는 크레딧이 부과될 수 있습니다.'],array['https://www.gumloop.com/blog/simplifying-gumloop-pricing','https://docs.gumloop.com/core-concepts/credits'],now(),now()),
('Dust','회사 데이터와 업무 앱을 연결해 팀별 AI 에이전트를 구축하는 플랫폼 #AI에이전트 #기업검색 #업무자동화 #MCP','Dust는 조직의 문서·메시지·업무 앱 문맥을 연결하고 도구와 MCP를 사용하는 팀별 AI 에이전트 및 자동화 워크플로를 구축하는 기업용 플랫폼입니다.','https://dust.tt/','https://dust.tt/favicon.ico','Freemium','$0','Free 1회 500크레딧 · 유료 좌석별 월 크레딧',array['Free seat는 평생 1회 500크레딧을 제공합니다.','Pro seat는 월 8,000크레딧, Max seat는 월 40,000크레딧을 제공합니다.','공개 문서에서 좌석의 최신 통화 가격은 확인되지 않아 결제 화면 또는 영업 문의가 필요합니다.'],'USD','https://dust.tt/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품·크레딧 문서를 확인했습니다. 최신 좌석 가격, 데이터 연결과 에이전트 실행은 직접 테스트하지 않았습니다.',false,true,'https://docs.dust.tt/reference','Native','specialized',array['기업 AI 에이전트','조직 지식 연결','도구 기반 자동화'],array['MCP 통합','다중 모델','관리·사용량 통제'],array['회사 문맥에 맞는 에이전트 구축','다양한 업무 데이터 연결','팀별 에이전트 공유'],array['사내 지식과 업무 앱을 연결하는 조직','부서별 AI 업무 도우미를 운영하는 팀'],array['정확한 최신 좌석 가격은 별도 확인이 필요합니다.','크레딧은 사용자별이며 미사용량이 이월되지 않습니다.','민감한 회사 데이터 연결 전 접근권한과 보존 정책을 검토해야 합니다.'],array['https://docs.dust.tt/docs/credits','https://dust.tt/'],now(),now())
) as seed(
  name,description,full_description,url,logo_url,pricing_type,pricing_start_at,
  pricing_summary,pricing_details,pricing_currency,pricing_url,pricing_verified_at,
  korean_support_level,is_verified,source_verified,hands_on_verified,api_tested,
  korean_tested,verification_level,verification_notes,is_domestic,has_api,api_url,
  ai_type,tool_scope,primary_features,secondary_features,key_benefits,best_for,
  limitations,verification_sources,verified_at,updated_at
)
where not exists (select 1 from public.tools where lower(tools.url)=lower(seed.url));

with assignments(tool_url, category_slug) as (values
  ('https://copilot.microsoft.com/','productivity'),('https://copilot.microsoft.com/','search-data'),
  ('https://manus.im/','productivity'),('https://manus.im/','search-data'),
  ('https://www.coderabbit.ai/','development'),('https://devin.ai/','development'),
  ('https://dify.ai/','development'),('https://dify.ai/','productivity'),
  ('https://www.read.ai/','productivity'),('https://www.read.ai/','video-audio'),
  ('https://relevanceai.com/','productivity'),('https://relevanceai.com/','business-marketing'),
  ('https://www.gumloop.com/','productivity'),('https://www.gumloop.com/','development'),
  ('https://dust.tt/','productivity'),('https://dust.tt/','search-data')
)
insert into public.tool_categories(tool_id,category_id)
select tools.id,categories.id from assignments
join public.tools on lower(tools.url)=lower(assignments.tool_url)
join public.categories on lower(categories.slug)=lower(assignments.category_slug)
on conflict(tool_id,category_id) do nothing;
